; ZX Spectrum UDG Sprite Data
; Generated by ZX Spectrum UDG Editor
;
; Sprite dimensions: 2x2 characters (16x16 pixels)
; Total characters: 4
; UDG data size: 32 bytes
; Attribute data size: 4 bytes

; -----------------------------------------------------------------------------
; Constants
; -----------------------------------------------------------------------------
SPRITE_WIDTH    equ 2          ; Width in characters
SPRITE_HEIGHT   equ 2          ; Height in characters
SPRITE_CHARS    equ 4         ; Total characters
UDG_BYTES       equ 32        ; Bytes of UDG pixel data
FIRST_UDG_CHAR  equ 144         ; First UDG character code

; -----------------------------------------------------------------------------
; UDG Pixel Data (8 bytes per character, MSB=leftmost pixel)
; -----------------------------------------------------------------------------
sprite_udg_data:
        defb $00,$01,$05,$0D,$1F,$1F,$1C,$08  ; char 0 (row 0, col 0)
        defb $00,$80,$A0,$B0,$F8,$F8,$38,$10  ; char 1 (row 0, col 1)
        defb $0B,$0B,$0C,$18,$17,$10,$0F,$00  ; char 2 (row 1, col 0)
        defb $D0,$D0,$30,$18,$E8,$08,$F0,$00  ; char 3 (row 1, col 1)

; -----------------------------------------------------------------------------
; Attribute Data (1 byte per character)
; Format: FBPPPIII where F=flash, B=bright, P=paper(0-7), I=ink(0-7)
; -----------------------------------------------------------------------------
sprite_attr_data:
        defb $47,$47  ; row 0
        defb $47,$47  ; row 1